package com.example.rokidgeminisecretary;import org.json.*;public class TransferPolicyTest{static int n;static void ok(boolean b){if(!b)throw new AssertionError(n);n++;}public static void main(String[] a)throws Exception{JSONObject j=new JSONObject().put("kind","photo").put("batchId","11111111-1111-4111-8111-111111111111").put("phase","COMPLETED").put("expected",5).put("confirmed",3).put("retained",2).put("secret","not public");JSONObject safe=TransferProgressPolicy.safe(j);ok(safe.getString("phase").equals("COMPLETED"));ok(!safe.has("secret"));ok(j.has("secret"));j.put("failed",1).put("retained",1);ok(TransferProgressPolicy.safe(j).getString("phase").equals("PARTIAL"));j.put("failed",0).put("retained",0).put("deferred",2);ok(TransferProgressPolicy.safe(j).getString("phase").equals("PARTIAL"));j.put("deferred",0);ok(TransferProgressPolicy.safe(j).getString("phase").equals("PARTIAL"));j.put("confirmed",5).put("unitsExpected",10).put("unitsConfirmed",9);ok(TransferProgressPolicy.safe(j).getString("phase").equals("PARTIAL"));j.put("unitsConfirmed",10);ok(TransferProgressPolicy.safe(j).getString("phase").equals("COMPLETED"));j.put("phase","unexpected");ok(TransferProgressPolicy.safe(j).getString("phase").equals("UNKNOWN"));j.put("expected",-100).put("confirmed",900);safe=TransferProgressPolicy.safe(j);ok(safe.getLong("expected")==0&&safe.getLong("confirmed")==0);j.put("kind","other");try{TransferProgressPolicy.safe(j);throw new AssertionError();}catch(IllegalArgumentException expected){n++;}System.out.println("PASS "+n+" transfer receipt checks");}}